#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <sys/syscall.h>
#include <sys/types.h>
#include <errno.h>

#define CLOCK_REALTIME 0
#define SIGEV_THREAD_ID 4

int main() {
    timer_t timerid;
    struct sigevent sev;
    struct itimerspec its;
    long tid = syscall(SYS_gettid);

    printf("Starting reproduction attempt...\n");

    // 1. Create timer for SIGCONT (18)
    sev.sigev_notify = SIGEV_THREAD_ID;
    sev.sigev_signo = SIGCONT;
    sev.sigev_value.sival_ptr = NULL;
    sev.sigev_notify_thread_id = tid;

    if (timer_create(CLOCK_REALTIME, &sev, &timerid) == -1) {
        perror("timer_create");
        return 1;
    }

    // 2. Start timer. Periodic.
    // Interval 10ms.
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 10000000;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 10000000;

    if (timer_settime(timerid, 0, &its, NULL) == -1) {
        perror("timer_settime");
        return 1;
    }

    // 3. Let it run for a bit. Since SIGCONT default is continue/ignore, it should be put on ignored list.
    printf("Timer running, sleeping 1s...\n");
    sleep(1);

    // 4. Now block SIGCONT.
    printf("Blocking SIGCONT...\n");
    sigset_t set;
    sigemptyset(&set);
    sigaddset(&set, SIGCONT);
    if (sigprocmask(SIG_BLOCK, &set, NULL) == -1) {
        perror("sigprocmask");
        return 1;
    }

    // 5. Let it run again. Now prepare_signal should return true (because blocked), but it's on ignored list.
    printf("Timer running with SIGCONT blocked, sleeping 1s...\n");
    sleep(1);

    printf("Done. Check dmesg.\n");
    return 0;
}

